<template>
  <q-layout view="lHh LpR lFf" class="min-height-unset">
    <q-header>
      <q-toolbar class="toolbar full-width toolbar-items">
        <div class="container row width-100-percent mt-mb-8">
          <q-avatar class="img_header cursor-pointer">
            <img
              src="https://fellowpro.com/wp-content/uploads/2023/06/LOGO_DocBits.png"
              @click="goHome"
              target="_blank"
            />
          </q-avatar>

          <div style="margin-left: auto; display: flex">
            <q-btn
              flat
              class="line-height mobile-hide"
              color="primary text-white "
              :label="$t('home')"
              @click="gotoCloud()"
            />

            <q-btn
              v-if="user_settings['WORKFLOW_BUILDER_MODULE_SETTING']"
              flat
              class="line-height mobile-hide"
              color="primary text-white "
              :label="$t('workflow')"
              @click="gotoWorkflow()"
            />
            <q-btn
              flat
              class="line-height mobile-hide"
              color="primary text-white "
              :label="$t('settings')"
              @click="gotoSettings()"
            />
            <q-btn
              v-if="user_settings['REPORT_PAGE']"
              flat
              class="line-height mobile-hide"
              color="primary text-white "
              :label="$t('report')"
              @click="gotoReport()"
            />
            <q-btn
              flat
              class="line-height mobile-hide"
              color="primary text-white "
              :label="$t('support')"
              @click="supportIntegration()"
              target="_blank"
            />

            <a v-if="showIcons" href="https://twitter.com/FConsultingAG" target="_blank" style="padding: 7px; color: inherit;" class="mobile-hide">
              <Icon icon="mdi:twitter" width="24" height="24" />
            </a>
            <a v-if="showIcons" href="https://www.facebook.com/fellowconsulting" target="_blank" style="padding: 7px; color: inherit;" class="mobile-hide">
              <Icon icon="mdi:facebook" width="24" height="24" />
            </a>
            <a v-if="showIcons" href="https://www.linkedin.com/company/fellow-consulting-ag/" target="_blank" style="padding: 7px; color: inherit;" class="mobile-hide">
              <Icon icon="mdi:linkedin" width="24" height="24" />
            </a>
            <!-- <LanguageDropdown /> -->

            <q-icon
              size="sm"
              class="mobile-only q-pa-sm"
              name="power_settings_new"
            />

            <Notifications />

            <AccountSettingDropdown />
          </div>
        </div>
      </q-toolbar>
    </q-header>

    <q-page-container>
      <router-view :key="$route.fullPath" />
    </q-page-container>
  </q-layout>
</template>

<script lang="ts">

import { defineComponent, ref } from 'vue';
import {
  useDropdownStore,
  useUserFontSizeStore,
  useSettingStore,
} from 'src/store/main';
import helperMixin from '../mixins/helperMixin.js';
import { storeToRefs } from 'pinia';
import { Dark } from 'quasar';
import { SUPPORT_URL } from 'src/pages/APIs';
import AccountSettingDropdown from 'src/components/LayoutHeader/AccountDropdown/main.vue';
import { dark_mode_setting } from 'src/constants';

export default defineComponent({
  name: 'MainLayout',
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal === false) {
          this.setDarkMode();
        }
      },
    },
  },
  unmounted() {
    document.removeEventListener('keydown', this.sendBack);
  },
  mounted: function () {
    document.addEventListener('keydown', this.sendBack);
    this.fillDocTypeAndSubTypesListIfEmpty();
    this.initFontSize();
    this.init();
  },
  methods: {
    init() {
      this.setDarkMode();
    },
    sendBack(event: any) {
      // document has q-dialog element
      if (event.key !== 'Escape' || document.querySelector('.q-dialog')) {
        return;
      }
      if (this.$route.path != '/dashboard') {
        this.$router.go(-1);
      }
    },

    setDarkMode() {
      const darkMode = this.user_settings[this.dark_mode_setting]
        ? true
        : false;
      if (darkMode) {
        this.$q.dark.set(true);
      }
      Dark.set(darkMode);
    },
    goHome() {
      this.$router.push('/dashboard');
    },
    supportIntegration() {
      this.$router.push('/support');
    },
    gotoSettings() {
      this.$router.push('/settings');
    },
    gotoReport() {
      this.$router.push('/report');
    },

    gotoCloud() {
      this.$router.push('/dashboard');
    },
    gotoWorkflow() {
      this.$router.push('/workflowsdashboard');
    },
  },
  data() {
    return {
      showIcons: false,
      supportURL: SUPPORT_URL,
      dark_mode_setting,
    };
  },
  components: {
    
    AccountSettingDropdown,
  },
  mixins: [helperMixin],

  setup() {
    const dropdown_store = useDropdownStore();
    const { fillDocTypeAndSubTypesListIfEmpty } = dropdown_store;

    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);

    const user_font_size_store = useUserFontSizeStore();
    const { initFontSize } = user_font_size_store;

    return {
      loading_settings,
      fillDocTypeAndSubTypesListIfEmpty,
      initFontSize,
      user_settings,
      settings_store,
      report: ref(true),
    };
  },
});
</script>

