<!--vbase-->
<template>
  <q-btn-dropdown
    class="user-setting q-ml-md account-header mobile-hide"
    :label="main_orgainzation"
    :loading="loading"
    data-test="user-menu-trigger"
  >
    <div class="row no-wrap q-pa-md">
      <div class="column">
        <q-list
          v-if="organizations"
          class="organizations-list"
          :style="
            hasSubOrganizations()
              ? {
                  'max-width': '314px',
                  'min-width': '314px',
                  'min-height': '136px',
                }
              : {}
          "
        >
          <template v-for="(organization, index) in organizations" :key="index">
            <q-item-label
              class="v-p-0 font-size-18 no-padding-left-right text-weight-bold"
              header
              >{{ organization.name }}</q-item-label
            >
            <q-separator />
            <div>
              <template
                v-for="(
                  sub_organization, index_sub
                ) in organization.sub_organisations"
                :key="index_sub"
              >
                <q-item
                  class="m-t-5 v-p-0 font-size-12 no-padding-left-right text-weight-bold"
                  clickable
                  v-ripple
                  @click="setSubOrg(sub_organization)"
                  :active="sub_organization.id === sub_org_id"
                >
                  <q-item-section avatar>
                    <q-icon
                      name="work"
                      :class="
                        sub_organization.id === sub_org_id
                          ? 'active-color'
                          : 'inactive-color'
                      "
                    />
                  </q-item-section>
                  <q-item-section
                    :class="
                      sub_organization.id === sub_org_id
                        ? 'active-color'
                        : 'inactive-color'
                    "
                    >{{ sub_organization.name }}</q-item-section
                  >
                </q-item>
              </template>
            </div>
          </template>
        </q-list>

        <q-separator />

        <div class="row">
          <div style="width: 50%">
            <DateFormat />
          </div>
          <div style="width: 50%" class="q-pl-sm">
            <AmountFormat />
          </div>
        </div>

        <div>
          <fontSizeOption />
        </div>

        <div>
          <darkModeOption />
        </div>

        <DualMonitor />

        <div class="text-weight-medium">
          <q-btn
            style="padding: 4px 6px"
            flat
            color="primary"
            @click="refreshClicked"
            icon="refresh"
            class="no-padding-left-right"
          />
          {{ $t('refresh_user_settings') }}
        </div>
      </div>

      <q-separator vertical inset class="q-mx-lg" />

      <div class="column items-center">
        <q-avatar size="72px" class="notification-item-avatar">
          <span class="notification-item-initials">
            {{ getInitials(userFullName) }}
          </span>
        </q-avatar>
        <label class="row q-ma-sm" @click="profileDialog = true">
          <q-icon
            name="edit"
            size="16px"
            color="primary"
            class="mt-3 cursor-pointer"
          >
            <q-tooltip>{{ $t('edit_profile') }}</q-tooltip>
          </q-icon>
          <span class="cursor-pointer link">{{ $t('edit_profile') }}</span>
        </label>
        <div class="text-subtitle1 q-mb-sm">{{ userFullName }}</div>

        <LanguageDropdown />

        <q-btn
          push
          size="sm"
          v-close-popup
          data-cy="logout"
          color="primary text-white "
          :label="$t('logout')"
          @click="logout()"
          icon="power_settings_new"
        />
      </div>
    </div>
  </q-btn-dropdown>

  <!-- Dialog starts -->
  <q-dialog v-model="profileDialog" persistent>
    <EditProfile />
  </q-dialog>
  <!-- dialog ends -->

  <!-- refresh Warning -->
  <q-dialog
    v-model="refresh_warning"
    persistent
    transition-show="scale"
    transition-hide="scale"
  >
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('change_lost_warning') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn
          appearance="cancel"
          :label="$t('cancel')"
          v-close-popup
          @click="refresh_warning = false"
        />
        <f-btn
          data-cy="done"
          :label="$t('proceed')"
          @click="refreshSettings(true)"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
  <!-- END Un Save Changes Warning -->
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import cache from 'src/utils/cache';
import { Acl } from 'src/core/acls/index';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import fontSizeOption from './fontSizeOption.vue';
import darkModeOption from './darkModeOption.vue';
import DateFormat from './DateFormat.vue';
import AmountFormat from './AmountFormat.vue';
import helperMixin from 'src/mixins/helperMixin.js';
import { UserSubOrg } from 'src/utils/organization/index';
import EditProfile from 'src/pages/User/Edit-Profile.vue';
import DualMonitor from './DualMonitor.vue';
import {
  useUserStore,
  useSettingStore,
  useLangOriginDropdownStore,
  useDocumentStore,
  useDatePatternDropdownStore,
} from 'src/store/main';
import { getUserDetailFromkey, isUserAdmin } from 'src/utils/UserDetails';
import LanguageDropdown from 'src/components/LayoutHeader/LanguageDropdown.vue';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  el: '#app',
  mixins: [cache, helperMixin],
  props: {},
  components: {
    EditProfile,
    DualMonitor,
    DateFormat,
    AmountFormat,
    fontSizeOption,
    darkModeOption,
    LanguageDropdown,
  },
  data() {
    return {};
  },
  mounted: function () {
    this.init();
    window.addEventListener('storage', this.storageChangeEvent);
  },
  unmounted: function () {
    window.removeEventListener('storage', this.storageChangeEvent);
  },
  methods: {
    getInitials(fullname: string) {
      var names = fullname.split(' '),
        initials: string = names[0].substring(0, 1).toUpperCase();

      if (names.length > 1) {
        initials += names[names.length - 1].substring(0, 1).toUpperCase();
      }
      return initials;
    },
    async init() {
      try {
        this.loading = true;
        await this.refreshSettings();
        await this.getSubOrgId();
        this.refreshUserInfo();
        this.getLanguageIfEmpty();
        this.getDatePatterns();
      } catch (err) {
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    storageChangeEvent(e: any) {
      this.handleSessionStorageChange(e);
    },

    async handleSessionStorageChange(event: any) {
      try {
        // this.handleStorageEvent(event);
        await this.refreshAndGetSubOrgId();
      } catch (err: any) {
        logError(err);
      } finally {
      }
    },

    async getDatePatterns() {
      if (this.date_pattern_loaded) {
        return;
      }
      await this.getDatePatternOptions();
    },

    async setSubOrg(selected_sub_org: any) {
      try {
        this.showLoading();
        const id = String(selected_sub_org.id);
        if (!id) {
          notify.error('no organization selected');
          return;
        }
        await UserSubOrg.setSubOrgId(id);
        await this.refreshAndGetSubOrgId();
        this.$router.go(0);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
      return;
    },

    refreshUserInfo() {
      this.profileDialog = false;
      const id = getUserDetailFromkey('id');
      this.isUserAdmin = getUserDetailFromkey('is_organisation_admin');

      if (id) {
        this.updateUserName();
      } else {
        this.logout();
      }
    },

    async refreshSettings(clear_sessions = false) {
      await this.startSettingsFetch();
      this.refresh_warning = false;
      if (!clear_sessions) {
        return;
      }
      this.clearStorageForRefresh();
      await Acl.fetch();
      await this.refreshUserOrganizations();
      // doc store

      const doc_store = useDocumentStore();
      doc_store.resetDocStore(this.$route.fullPath);
      this.$router.go(0);
    },

    refreshClicked() {
      const route_name = this.$route.path;
      const nonwarningRoutes = ['/dashboard', '/setting'];
      if (nonwarningRoutes.includes(route_name)) {
        this.refreshSettings(true);
        return;
      }
      this.refresh_warning = true;
    },

    hasSubOrganizations() {
      if (
        this.organizations[0] &&
        this.organizations[0].hasOwnProperty('sub_organisations') &&
        this.organizations[0].sub_organisations.length > 0
      ) {
        return true;
      }
      return false;
    },
  },
  setup() {
    const user_store = useUserStore();
    const {
      updateUserName,
      getUserOrganizations,
      getSubOrgId,
      refreshAndGetSubOrgId,
      refreshUserOrganizations,
    } = user_store;
    const { userFullName, organizations, sub_org_id, main_orgainzation } =
      storeToRefs(user_store);

    const settings_store = useSettingStore();
    const { startSettingsFetch } = settings_store;

    const language_origin_dropdown = useLangOriginDropdownStore();
    const { getLanguageIfEmpty } = language_origin_dropdown;

    const date_pattern_dropdown = useDatePatternDropdownStore();
    const { getDatePatternOptions } = date_pattern_dropdown;
    const { date_pattern_loaded } = storeToRefs(date_pattern_dropdown);

    return {
      startSettingsFetch,
      refreshUserOrganizations,
      refreshAndGetSubOrgId,
      date_pattern_loaded,
      getDatePatternOptions,
      getLanguageIfEmpty,
      getUserOrganizations,
      updateUserName,
      getSubOrgId,
      settings_store,
      main_orgainzation,
      sub_org_id,
      userFullName,
      organizations,
      refresh_warning: ref(false),
      profileDialog: ref(false),
      isUserAdmin: ref(''),
      link: ref('inbox'),
      loading: ref(false),
    };
  },
});
</script>

